import{c as i,ah as s,L as a,O as t}from"./chunks/framework.YKVbmyBD.js";const g=JSON.parse('{"title":"输入/输出重定向","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/use-cli/io-redirection.md","filePath":"fovlin-notes/linux-guide/use-cli/io-redirection.md"}'),l={name:"fovlin-notes/linux-guide/use-cli/io-redirection.md"};function n(d,e,o,c,h,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="输入-输出重定向" tabindex="-1">输入/输出重定向 <a class="header-anchor" href="#输入-输出重定向" aria-label="Permalink to “输入/输出重定向”">​</a></h1><h2 id="输出重定向" tabindex="-1">输出重定向 <a class="header-anchor" href="#输出重定向" aria-label="Permalink to “输出重定向”">​</a></h2><p>在终端中，可以使用 <code>&gt;</code> 或 <code>&gt;&gt;</code> 将输出重定向到文件中，其中 <code>&gt;</code> 表示覆盖文件，<code>&gt;&gt;</code> 表示添加到文件的尾行。</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command &gt; file</span></span></code></pre></div><p>例如，<code>echo</code> 命令将输出指定的变量或字符串，可以通过输出重定向快速写入内容到文件，例如想在 <code>.bashrc</code> 的尾行加入一条内容 <code>alias ll=&#39;ls -lh --color=auto&#39;</code>：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;alias ll=&#39;ls -lh --color=auto&#39;&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .bashrc</span></span></code></pre></div><p>这将在尾行追加该内容，你也可以使用 <code>&gt;</code> 覆盖整个文件。</p><h2 id="输入重定向" tabindex="-1">输入重定向 <a class="header-anchor" href="#输入重定向" aria-label="Permalink to “输入重定向”">​</a></h2><p>可以将文件内容使用 <code>&lt;</code> 输入给命令：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command &lt; file</span></span></code></pre></div><p><code>wc -m</code> 命令可以统计字数，通过输入重定向，即可统计文件字数，例如统计 <code>README.md</code> 文件字符数：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span></code></pre></div><p>内容将以字符串传递给前方命令，即使该命令和 <code>wc -m README.md</code> 效果一样，但前者通过倾向于统计字符串个数，后者倾向于读取文件内字符串个数。</p><h2 id="过滤文件描述符的输出重定向" tabindex="-1">过滤文件描述符的输出重定向 <a class="header-anchor" href="#过滤文件描述符的输出重定向" aria-label="Permalink to “过滤文件描述符的输出重定向”">​</a></h2><p>文件描述符是操作系统中用于标识打开的文件的一个整数。</p><p>在 Unix 和 Linux 系统中，每个进程在启动时会自动打开三个标准的文件描述符：</p><ul><li><p><code>0</code>：标准输入（stdin）</p></li><li><p><code>1</code>：标准输出（stdout）</p></li><li><p><code>2</code>：标准错误（stderr）</p></li></ul><p>使用 <code>n&gt;</code> 的方式来过滤输出，其中 <code>n</code> 为指定的文件描述符。</p><p>例如要将错误信息输出到文件 <code>error.log</code> 中，可以使用如下格式的命令</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command 2&gt; error.log</span></span></code></pre></div><p>同样的，你可以用 <code>n&gt;&gt;</code> 的方式将输出追加到文件尾行。</p><h2 id="here-document" tabindex="-1">Here Document <a class="header-anchor" href="#here-document" aria-label="Permalink to “Here Document”">​</a></h2><p>使用 <code>&lt;&lt;</code> 可以交互式将输入内容输入到 Shell 程序中，例如在终端中输入以下命令，回车后将允许你继续输入内容，直到你再此输入 <code>maker</code>，<code>maker</code>是一个标记，你可以将他替换为任意字符串。</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -m &lt;&lt; maker</span></span>
<span class="line"><span>&gt; Acovia docs</span></span>
<span class="line"><span>&gt; maker</span></span>
<span class="line"><span>12</span></span>
<span class="line"><span>$</span></span></code></pre></div><h2 id="组合重定向" tabindex="-1">组合重定向 <a class="header-anchor" href="#组合重定向" aria-label="Permalink to “组合重定向”">​</a></h2><p>如果你希望将多个文件描述符的内容写入文件，可以组合写入，格式如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command &gt; out.log 2&gt;&amp;1</span></span></code></pre></div><p><code>&amp;</code> 将合并这两个输入符的输出。</p>`,28)])])}const k=i(l,[["render",n]]);export{g as __pageData,k as default};
